;## kw_pow
;kw_pow, <basevar>, <expvar>, <destvar>  - base ^ exp (Integer, low 16 bits; exp < 0 gives 0)
kw_pow:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld hl, 1
			bit 7, d
			jr z, ntc_pw_go
			ld hl, 0
			jr ntc_pw_st
ntc_pw_go:
			ld a, d
			or e
			jr z, ntc_pw_st
			ld (ntc_pwe), de
			ex de, hl
			ld hl, 0
			ld a, 16
ntc_pw_mul:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_pw_sk
			add hl, bc
ntc_pw_sk:
			dec a
			jr nz, ntc_pw_mul
			ld de, (ntc_pwe)
			dec de
			jr ntc_pw_go
ntc_pw_st:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret
ntc_pwe:		dw 0

ntc_rg780_e:
			IF ($ < 58624) && (ntc_rg781_e - ntc_rg781 + $ > 48640)	; fwdref-ok
