;## ntc_fmt ntc_data
; Format$ with a number pattern. ntc_fmbuf holds "-123" (ntc_itoa / ntc_ltoa);
; the thread has <mindigits>, <group>, <prefix>, <suffix>. Writes to (ntc_fmd).
ntc_fm_common:
			pop bc
			ld a, c
			ld (ntc_fmmin), a
			pop bc
			ld a, c
			ld (ntc_fmgrp), a
			pop hl
			ld (ntc_fmpre), hl
			pop hl
			ld (ntc_fmsuf), hl
			ld de, (ntc_fmd)
			ld hl, ntc_fmbuf
			ld a, (hl)
			cp '-'
			jr nz, ntc_fm_pos
			ld (de), a
			inc de
			inc hl
ntc_fm_pos:
			ld (ntc_fmdig), hl
			ld hl, (ntc_fmpre)
ntc_fm_pre:
			ld a, (hl)
			or a
			jr z, ntc_fm_cnt
			ld (de), a
			inc de
			inc hl
			jr ntc_fm_pre
ntc_fm_cnt:
			ld hl, (ntc_fmdig)
			ld b, 0
ntc_fm_c1:
			ld a, (hl)
			or a
			jr z, ntc_fm_c2
			inc hl
			inc b
			jr ntc_fm_c1
ntc_fm_c2:
			ld c, 0
			ld a, (ntc_fmmin)
			sub b
			jr c, ntc_fm_c3
			ld c, a
ntc_fm_c3:
			ld a, b
			add a, c
			ld (ntc_fmk), a
ntc_fm_mod:
			cp 4
			jr c, ntc_fm_m2
			sub 3
			jr ntc_fm_mod
ntc_fm_m2:
			ld (ntc_fmm), a
			ld hl, (ntc_fmdig)
ntc_fm_out:
			ld a, (ntc_fmk)
			or a
			jr z, ntc_fm_suf
			ld a, c
			or a
			jr z, ntc_fm_d
			dec c
			ld a, '0'
			jr ntc_fm_put
ntc_fm_d:
			ld a, (hl)
			inc hl
ntc_fm_put:
			ld (de), a
			inc de
			ld a, (ntc_fmk)
			dec a
			ld (ntc_fmk), a
			ld a, (ntc_fmm)
			dec a
			ld (ntc_fmm), a
			jr nz, ntc_fm_out
			ld a, 3
			ld (ntc_fmm), a
			ld a, (ntc_fmk)
			or a
			jr z, ntc_fm_suf
			ld a, (ntc_fmgrp)
			or a
			jr z, ntc_fm_out
			ld a, ','
			ld (de), a
			inc de
			jr ntc_fm_out
ntc_fm_suf:
			ld hl, (ntc_fmsuf)
ntc_fm_s1:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
